import {motionPreference} from './preferences.js';
export function animateIn(el,delay=0){if(motionPreference.matches||!el?.animate)return;el.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:480,delay:delay*1000,easing:'cubic-bezier(.16,1,.3,1)'});}
export function setupMotion({tone}){
 const fine=matchMedia('(hover:hover) and (pointer:fine)'),hero=document.querySelector('.hero'),cursor=document.querySelector('.cursor-orbit');let pointerX=0,pointerY=0,cursorFrame=0,scrollFrame=0,currentTilt,disposeLens;
 function stopPointer(){document.querySelectorAll('[style*="--tilt"],[style*="--mag-"]').forEach(el=>{el.style.removeProperty('--tilt-x');el.style.removeProperty('--tilt-y');el.style.removeProperty('--mag-x');el.style.removeProperty('--mag-y');});cursor?.classList.remove('active');}
 function pointer(e){if(!fine.matches||motionPreference.matches)return;pointerX=e.clientX;pointerY=e.clientY;if(!cursorFrame)cursorFrame=requestAnimationFrame(()=>{cursorFrame=0;cursor.style.transform=`translate3d(${pointerX}px,${pointerY}px,0) translate(-50%,-50%)`;cursor.classList.add('active');cursor.classList.remove('hidden');});
 const card=e.target.closest('.certificate-card');if(currentTilt&&currentTilt!==card){currentTilt.style.setProperty('--tilt-x','0deg');currentTilt.style.setProperty('--tilt-y','0deg');}currentTilt=card;if(card){const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${-(e.clientY-r.top-r.height/2)/r.height*6}deg`);card.style.setProperty('--tilt-y',`${(e.clientX-r.left-r.width/2)/r.width*8}deg`);}
 if(hero.classList.contains('is-inview')){hero.style.setProperty('--portrait-x',`${(e.clientX/innerWidth-.5)*9}px`);hero.style.setProperty('--portrait-y',`${(e.clientY/innerHeight-.5)*7}px`);hero.style.setProperty('--light-x',`${(e.clientX/innerWidth-.5)*25}px`);hero.style.setProperty('--light-y',`${(e.clientY/innerHeight-.5)*20}px`);}
 const magnetic=e.target.closest('.magnetic');if(magnetic){const r=magnetic.getBoundingClientRect();magnetic.style.setProperty('--mag-x',`${(e.clientX-r.left-r.width/2)*.13}px`);magnetic.style.setProperty('--mag-y',`${(e.clientY-r.top-r.height/2)*.2}px`);}
 }
 document.addEventListener('pointermove',pointer,{passive:true});document.addEventListener('pointerover',e=>{if(!fine.matches||motionPreference.matches)return;const target=e.target.closest('[data-cursor],a,button');cursor.classList.toggle('engaged',Boolean(target?.dataset.cursor));cursor.querySelector('span').textContent=target?.dataset.cursor||'';if(target&&['.certificate-card','.project-button','.primary'].some(s=>target.matches(s))&&!target.contains(e.relatedTarget))tone('hover');});
 document.addEventListener('pointerout',e=>{const magnetic=e.target.closest('.magnetic');if(magnetic&&!magnetic.contains(e.relatedTarget)){magnetic.style.setProperty('--mag-x','0px');magnetic.style.setProperty('--mag-y','0px');}});document.addEventListener('pointerleave',()=>cursor.classList.add('hidden'));
 document.addEventListener('click',e=>{if(motionPreference.matches)return;const target=e.target.closest('.primary,.sound,.gallery-view button');if(!target)return;const r=target.getBoundingClientRect(),span=document.createElement('span');span.className='ripple';span.style.left=`${e.clientX-r.left}px`;span.style.top=`${e.clientY-r.top}px`;span.setAttribute('aria-hidden','true');target.append(span);span.addEventListener('animationend',()=>span.remove(),{once:true});});
 const revealed=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealed.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.section-top,.intro h2,.intro-aside,.project,.article,.timeline,.contact h2').forEach(el=>{el.classList.add('reveal');revealed.observe(el);});
 const inView=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('is-inview',e.isIntersecting)),{rootMargin:'40px'});document.querySelectorAll('.section,.hero').forEach(el=>inView.observe(el));
 const navLinks=[...document.querySelectorAll('nav a')];function updateScroll(){scrollFrame=0;const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=`${max>0?scrollY/max*100:0}%`;document.querySelector('header').classList.toggle('scrolled',scrollY>40);let active=null;for(const a of navLinks){const el=document.querySelector(a.getAttribute('href'));if(el&&el.getBoundingClientRect().top<innerHeight*.45)active=a;}navLinks.forEach(a=>{a.classList.toggle('active',a===active);if(a===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});if(!motionPreference.matches)document.querySelectorAll('.film.is-inview,.contact.is-inview').forEach(el=>el.style.setProperty('--section-shift',`${Math.max(-30,Math.min(30,el.getBoundingClientRect().top*.035))}px`));}
 addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateScroll);},{passive:true});updateScroll();
 let lensStarted=false;function loadLens(){if(lensStarted||motionPreference.matches||navigator.connection?.saveData||(navigator.deviceMemory&&navigator.deviceMemory<=2))return;lensStarted=true;const canvas=document.createElement('canvas');let context;try{context=canvas.getContext('webgl2',{alpha:true,antialias:!matchMedia('(pointer:coarse)').matches,powerPreference:'low-power',failIfMajorPerformanceCaveat:true});}catch{}if(!context)return;import('./scene.js').then(module=>{if(motionPreference.matches)return;disposeLens=module.mountLens(document.querySelector('#lens-sculpture'),canvas,context,motionPreference);}).catch(()=>{/* The original SVG sculpture remains available without WebGL. */});}
 const lazy=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){if('requestIdleCallback'in window)requestIdleCallback(loadLens,{timeout:2000});else setTimeout(loadLens,700);lazy.disconnect();}},{rootMargin:'100px'});lazy.observe(hero);
 motionPreference.addEventListener('change',()=>{if(motionPreference.matches){stopPointer();hero.style.removeProperty('--portrait-x');hero.style.removeProperty('--portrait-y');document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));disposeLens?.();disposeLens=undefined;lensStarted=false;}else{loadLens();}});fine.addEventListener('change',()=>{if(!fine.matches)stopPointer();});
 return()=>{disposeLens?.();revealed.disconnect();inView.disconnect();lazy.disconnect();cancelAnimationFrame(scrollFrame);cancelAnimationFrame(cursorFrame);};
}
